BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
W=[
E('anodyne','/ˈænədaɪn/','不刺激人的；平淡乏味的；止痛的；慰藉或止痛物〔名词〕','一句话圆滑到没有棱角，谁也不得罪，却也几乎没说什么，可以叫 anodyne。把“不让人痛”移到语言上，就成了“不触痛任何人”的平淡表达。','接希腊 anōdynos“无痛的”，由 an-“没有”与 odynē“疼痛”组成，经拉丁及中世纪拉丁 anodynus 一系借入英语。原有止痛、减轻痛苦的用法；后来发展出温和、不冒犯乃至乏味的意思。',[['希腊 an-；odynē','没有；疼痛'],['希腊 anōdynos → 拉丁／中世纪拉丁 anodynus','无痛的；减轻疼痛的'],['英语 anodyne','止痛的、止痛物；进一步指安抚、无刺激或乏味的表达']],'an anodyne statement 常带一点批评：听来无害，但避开了真正的问题。名词 an anodyne for anxiety 则可指让焦虑暂时缓和的慰藉，不一定是药物。词义从身体的疼痛扩展到精神不适，再扩展到言语是否刺人。','an anodyne statement；anodyne remarks；an anodyne for grief；anodyne effects。形容词的平淡义在评论中较常见，医学义偏正式。','neutral 只是中立，不一定乏味；anodyne 常暗示表达磨掉了锋芒。名词的慰藉义可以是比喻，不应一律译成镇痛药。',('The company issued an anodyne statement that answered none of the main questions.','公司发布了一份不痛不痒的声明，没有回答任何主要问题。'),('The interview was full of anodyne remarks about working together.','访谈里尽是关于共同合作的平淡套话。'),('For him, familiar music was an anodyne for loneliness.','对他来说，熟悉的音乐是排遣孤独的一种慰藉。'),sources=['https://www.etymonline.com/word/anodyne','https://www.oxfordlearnersdictionaries.com/definition/english/anodyne','https://en.wiktionary.org/wiki/anodyne#English']),
E('allodynia','美 /ˌæloʊˈdɪniə/〔也有 /ˌælə-/ 读法〕','触诱发痛；异常性疼痛〔通常不致痛的刺激引起疼痛〕','衣料轻轻擦过，本来通常只会有触感，却让人觉得疼。这个词抓住的是“本不该痛的刺激，带来了痛感”这一变化。','20 世纪疼痛术语，all(o)- 接希腊 allos“别的、不同的”，-odynia 接 odynē“疼痛”和状态名词形式 -ia。这里的“不同”是感觉反应偏离通常情况，不是说身体另一边在痛。',[['希腊 allos；odynē + -ia','不同的；疼痛及状态形式'],['近代临床术语 allo- + -odynia','命名通常不致痛的刺激引起疼痛'],['英语 allodynia','用于描述这一疼痛现象，而不单独指定其机制']],'它描述刺激和感受的关系，不是凭这个名称就说明了全部病因。轻触只是便于理解的例子，温度等其他刺激也可能涉及。与原本会痛、现在痛得更厉害相比，这里的关键是通常不痛的刺激变得会痛。','tactile allodynia〔触觉性异常疼痛〕；experience allodynia；an explanation of allodynia。一般用作不可数名词。','hyperalgesia 强调通常会痛的刺激引发更强疼痛；allodynia 强调通常不致痛的刺激也引起疼痛。两者可并存，不是非此即彼。',('The leaflet explains how a light touch can become painful in allodynia.','小册子解释了在异常性疼痛中，轻触为何也会带来痛感。'),('The study distinguishes allodynia from an increased response to normally painful stimuli.','这项研究区分了异常性疼痛与对通常致痛刺激反应增强的情况。'),sources=['https://www.merriam-webster.com/dictionary/allodynia','https://www.iasp-pain.org/resources/terminology/']),
]
names=[x['word'] for x in W];cat=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text()) if x['id']=='C0863');EX={w:'较冷门的部位性疼痛细分名称，按当前通用阅读范围暂略。' for w in cat['family'] if w not in names}
ROOT=dict(id='C0863',meaning='疼痛；痛苦',core='odyn- 接希腊 odynē“疼痛”。一个词加上“没有”，走向减轻痛苦；另一个加上“不同”，描述刺激与痛感的异常关系。',image='an- 无 + 疼痛 → anodyne 止痛、安抚，后来也指平淡无刺激；allo- 不同 + 疼痛 → allodynia 通常不致痛的刺激引起疼痛。',intro='先记两个具体场景：一句没有锋芒的声明，与衣料轻触却引起痛感。前者是语言评论，后者是严格定义的临床现象。',forms='anodyne 经希腊形容词和拉丁借入，历史较早；allodynia 是近代用希腊来源成分构造的术语。不能把两个词当成同时由英语 odyn 现拼出来。',branches=[['从止痛到不痛不痒的表达','anodyne'],['通常不致痛的刺激引起疼痛','allodynia']],contrasts='anodyne 的平淡义不是骂人麻木；allodynia 也不是“所有疼痛”的总称。理解临床词时，看它描述什么现象，不由字面直接推出病因。',practice='把 anodyne statement 译成“不痛不痒的声明”，再用轻触的例子解释 allodynia；注意两处“痛”的实际语境不同。',words=names,exclude=EX)
